<?php
require_once __DIR__ . '/app.php'; require_login(); $me=current_user(); $error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$display=trim((string)($_POST['display_name']??''));$bio=trim((string)($_POST['bio']??''));try{if($display===''||mb_strlen($display)>60)throw new RuntimeException('Display name is required and must be 60 characters or fewer.');if(mb_strlen($bio)>500)throw new RuntimeException('Bio must be 500 characters or fewer.');$path=upload_image('avatar');if($path){$stmt=$conn->prepare('UPDATE users SET display_name=?,bio=?,avatar_path=? WHERE id=?');$stmt->bind_param('sssi',$display,$bio,$path,$me['id']);}else{$stmt=$conn->prepare('UPDATE users SET display_name=?,bio=? WHERE id=?');$stmt->bind_param('ssi',$display,$bio,$me['id']);}$stmt->execute();$stmt=$conn->prepare('SELECT id,username,display_name,email,avatar_path,bio FROM users WHERE id=?');$stmt->bind_param('i',$me['id']);$stmt->execute();$_SESSION['user']=$stmt->get_result()->fetch_assoc();flash('Your profile has been updated.');redirect('profile.php');}catch(Throwable $e){$error=$e instanceof RuntimeException?$e->getMessage():'Could not update your profile.';}}
page_start('Edit profile');?>
<main class="content-wrap narrow-wrap"><div class="section-heading"><div><span class="eyebrow muted">MAKE IT YOURS</span><h1>Edit profile<span class="heading-dot">.</span></h1></div><a class="subtle-link" href="profile.php">Cancel</a></div><section class="card edit-card"><div class="edit-intro"><img class="profile-avatar edit-avatar" src="<?= e(avatar($me)) ?>" alt=""><div><h2>Your public profile</h2><p class="muted">Help people recognise you and know what you’re about.</p></div></div><?php if($error): ?><div class="form-error"><?= e($error) ?></div><?php endif; ?><form method="post" enctype="multipart/form-data" class="form-stack"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><label>Display name<input name="display_name" maxlength="60" required value="<?= e($_POST['display_name']??$me['display_name']) ?>"></label><label>Bio<textarea name="bio" rows="4" maxlength="500" placeholder="A few words about you…"><?= e($_POST['bio']??$me['bio']) ?></textarea><small class="field-hint">Up to 500 characters.</small></label><label>Profile photo<input class="file-input" type="file" name="avatar" accept="image/jpeg,image/png,image/webp,image/gif"><small class="field-hint">JPG, PNG, WEBP, or GIF · Maximum 8 MB.</small></label><button class="btn primary" type="submit">Save changes <span>→</span></button></form></section></main>
